import { Component, Element, Event, EventEmitter, h, Host, Prop, Watch } from '@stencil/core';

/**
 * @slot content - named slot 'content', here is any HTML content allowed.
 */
@Component({
  tag: 'groupui-step-vertical',
  styleUrl: 'step-vertical.scss',
  shadow: true,
})
export class StepVertical {
  /**
   * Groupui icon name
   */
  @Prop({ reflect: true }) readonly icon: string;
  /**
   * hidden attribute
   */
  @Prop({ reflect: true }) readonly number: number;
  /**
   * Defines if the step vertical is done
   */
  @Prop({ reflect: true }) readonly done: boolean = false;
  /**
   * Defines if the step vertical is currently active
   */
  @Prop({ reflect: true }) readonly active: boolean = false;

  /**
   * disables the step
   */
  @Prop({ reflect: true }) readonly disabled: boolean = false;

  /**
   * dispatched when step vertical is getting active
   */
  @Event({ bubbles: false }) groupuiStepActive: EventEmitter<number>;
  /**
   * dispatched when step vertical is getting done
   */
  @Event({ bubbles: false }) groupuiStepDone: EventEmitter<number>;

  @Element() host: HTMLElement;

  @Watch('active')
  emitActive() {
    if (this.active) {
      this.groupuiStepActive.emit(this.number);
    }
  }

  @Watch('done')
  emitDone() {
    if (this.done) {
      this.groupuiStepDone.emit(this.number);
    }
  }

  private getContent() {
    if (this.done) {
      const iconName = this.icon ? this.icon : 'check-24';
      return <groupui-icon name={iconName}></groupui-icon>;
    }
    return this.icon ? <groupui-icon name={this.icon}></groupui-icon> : this.number;
  }

  render() {
    return (
      <Host>
        <div
          class="step-container"
          role="listitem"
          aria-current={this.active && 'true'}
          aria-disabled={this.disabled && 'true'}
          aria-label={`Step ${this.number} ${this.done ? ', completed' : ''}`}
        >
          <div class="step">
            <div aria-hidden="true" class="step-indicator">
              <div class="step-indicator-content">{this.getContent()}</div>
            </div>
            <div id="title" class="step-title">
              <slot />
            </div>
          </div>
          <div id="content">
            <div role="separator" aria-hidden="true" id="line"></div>
            {this.active && <slot name="content" />}
          </div>
        </div>
      </Host>
    );
  }
}
